package org.brightstats.stats;

import com.google.gson.*;
import java.nio.file.*;
import java.util.*;

public final class NcaChecks {
    private static int checks;private static double maximum;
    private static void check(boolean value){checks++;if(!value)throw new AssertionError("NCA check "+checks);}
    private static void close(double a,double b,String label){checks++;if(Double.isNaN(a)&&Double.isNaN(b))return;double d=Math.abs(a-b);if(!Double.isFinite(d)||d>1e-10*Math.max(1,Math.abs(b)))throw new AssertionError(label+": "+a+" != "+b);maximum=Math.max(maximum,d);}
    private static void reject(Runnable work){try{work.run();throw new AssertionError("Invalid NCA accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        Gson gson=new GsonBuilder().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonObject reference=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonObject();JsonArray cases=new JsonArray();int nativeCases=0;
        for(var element:reference.getAsJsonArray("cases")){
            var value=element.getAsJsonObject();double[] x=gson.fromJson(value.get("x"),double[].class),y=gson.fromJson(value.get("y"),double[].class);double[][] predictors=new double[x.length][1];for(int i=0;i<x.length;i++)predictors[i][0]=x[i];var fit=Nca.fit(predictors,y,List.of("X"),"Y",Nca.Options.defaults());var condition=fit.conditions().get(0);double area=condition.scopeArea();
            close(condition.ceFdh().ceilingArea(),value.get("ceArea").getAsDouble(),"Native CE area");close(condition.crFdh().ceilingArea(),value.get("crArea").getAsDouble(),"Native CR area");close(condition.crFdh().slope(),value.get("slope").getAsDouble(),"Native CR slope");close(condition.crFdh().intercept(),value.get("intercept").getAsDouble(),"Native CR intercept");
            var points=value.getAsJsonArray("frontier");check(points.size()==condition.ceilingPoints().size());for(int i=0;i<points.size();i++){var point=points.get(i).getAsJsonArray();close(condition.ceilingPoints().get(i).x(),point.get(0).getAsDouble(),"Native frontier X");close(condition.ceilingPoints().get(i).y(),point.get(1).getAsDouble(),"Native frontier Y");}
            for(int i=0;i<=10;i++){var row=value.getAsJsonArray("requirements").get(i).getAsJsonArray();double target=row.get(0).getAsDouble();for(int method=0;method<2;method++){double expected=row.get(method+1).getAsDouble();var actual=(method==0?condition.ceBottlenecks():condition.crBottlenecks()).get(i);close(actual.requiredCondition(),expected,"Native bottleneck");if(Double.isFinite(expected)){int count=0;for(double observed:x)if(observed<expected)count++;close(actual.countBelow(),count,"Strict condition count");}int count=0;for(double observed:y)if(observed<target)count++;close(actual.outcomePercentile(),100.0*count/y.length,"Strict outcome percentile");}}
            for(int i=0;i<condition.sensitivity().size();i++)close(condition.sensitivity().get(i).empiricalEffectSize(),value.getAsJsonArray("sensitivity").get(i).getAsJsonObject().get("area").getAsDouble()/area,"Native ECDF ceiling");
            var nativePermutation=NcaPermutation.fit(predictors,y,List.of("X"),"Y",Nca.Options.defaults(),new NcaPermutation.Options(80,42,.05,RegressionBootstrap.Convention.REFERENCE_4_1_2_1,true),null);
            for(int j=0;j<2;j++)close(nativePermutation.tests().get(j).criticalEffect(),value.getAsJsonArray("criticalEffect").get(j).getAsDouble(),"Native critical effect");
            for(int j=0;j<2;j++){close(nativePermutation.tests().get(j).pValue(),value.getAsJsonArray("permutationP").get(j).getAsDouble(),"Native permutation P");double[] distribution=nativePermutation.tests().get(j).distribution();for(int i=0;i<80;i++)close(distribution[i],value.getAsJsonArray("nullEffects").get(i).getAsJsonArray().get(j).getAsDouble(),"Native null effect");}
            JsonObject test=new JsonObject();test.add("predictors",gson.toJsonTree(predictors));test.add("response",gson.toJsonTree(y));test.add("options",gson.toJsonTree(fit.options()));test.add("result",gson.toJsonTree(fit));cases.add(test);nativeCases++;
        }
        int permutationCases=0;for(var element:reference.getAsJsonArray("permutations")){var value=element.getAsJsonObject();int n=value.get("n").getAsInt();int[] actual=ReferenceResampling.permutation(value.get("seed").getAsLong(),n),expected=gson.fromJson(value.get("rows"),int[].class);check(Arrays.equals(actual,expected));check(Arrays.stream(actual).distinct().count()==n);permutationCases++;}
        double[][] perfect={{0},{.5},{1}};double[] perfectY={0,.5,1};var fit=Nca.fit(perfect,perfectY,List.of("X"),"Y",Nca.Options.defaults());close(fit.conditions().get(0).ceFdh().effectSize(),.75,"Perfect CE");close(fit.conditions().get(0).crFdh().effectSize(),.5,"Perfect CR");
        var reverse=Nca.fit(perfect,new double[]{1,.5,0},List.of("X"),"Y",Nca.Options.defaults());check(!reverse.conditions().get(0).crFdh().regressionAvailable());close(reverse.conditions().get(0).ceFdh().effectSize(),0,"Reverse CE");check(reverse.conditions().get(0).warnings().size()==1);
        var wide=new Nca.Options(10,List.of(new Nca.Bounds(-1,2)),new Nca.Bounds(-1,2),.05,.005,1e-12);var theoretical=Nca.fit(perfect,perfectY,List.of("X"),"Y",wide);close(theoretical.conditions().get(0).ceFdh().effectSize(),23.0/36,"Full theoretical scope");close(theoretical.conditions().get(0).crFdh().effectSize(),.5,"Full theoretical CR scope");
        for(var convention:RegressionBootstrap.Convention.values()){
            var source=cases.get(1).getAsJsonObject();double[][] predictors=gson.fromJson(source.get("predictors"),double[][].class);double[] y=gson.fromJson(source.get("response"),double[].class);var options=new NcaPermutation.Options(80,42,.05,convention,true);var permutation=NcaPermutation.fit(predictors,y,List.of("X"),"Y",Nca.Options.defaults(),options,null);check(permutation.successful()==80&&permutation.failed()==0);for(var test:permutation.tests()){check(test.distribution().length==80);check(Arrays.stream(test.histogram().counts()).sum()==80);check(test.pValue()>=0&&test.pValue()<=1);}
            JsonObject test=new JsonObject();test.add("predictors",gson.toJsonTree(predictors));test.add("response",gson.toJsonTree(y));test.add("options",gson.toJsonTree(Nca.Options.defaults()));test.add("permutationOptions",gson.toJsonTree(options));test.add("permutation",gson.toJsonTree(permutation));cases.add(test);
            var zero=NcaPermutation.fit(perfect,new double[]{1,.5,0},List.of("X"),"Y",Nca.Options.defaults(),new NcaPermutation.Options(30,42,.05,convention,false),null);check(convention==RegressionBootstrap.Convention.STANDARD?zero.tests().get(0).pValue()==1:Double.isNaN(zero.tests().get(0).pValue()));check(zero.tests().get(0).distribution()==null);
        }
        reject(()->Nca.fit(new double[][]{{1},{1},{1}},perfectY,List.of("X"),"Y",Nca.Options.defaults()));reject(()->Nca.fit(perfect,new double[]{1,1,1},List.of("X"),"Y",Nca.Options.defaults()));reject(()->Nca.fit(perfect,new double[]{1,Double.NaN,2},List.of("X"),"Y",Nca.Options.defaults()));reject(()->Nca.fit(perfect,perfectY,List.of("X"),"Y",new Nca.Options(10,List.of(new Nca.Bounds(.1,1)),null,.05,.005,1e-12)));reject(()->new Nca.Options(0,List.of(),null,.05,.005,1e-12));reject(()->new Nca.Bounds(1,1));reject(()->new NcaPermutation.Options(29,42,.05,RegressionBootstrap.Convention.STANDARD,false));
        Thread.currentThread().interrupt();try{Nca.fit(perfect,perfectY,List.of("X"),"Y",Nca.Options.defaults());throw new AssertionError("NCA ignored cancellation");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        reject(()->Nca.fit(perfect,perfectY,List.of("X"),"Y",new Nca.Options(10,List.of(new Nca.Bounds(-1e100,1e100)),null,.05,.005,1e-12)));
        Thread.currentThread().interrupt();try{ReferenceResampling.permutation(42,100);throw new AssertionError("Permutation ignored cancellation");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Path output=Path.of(args[1]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"native_geometry_cases\":"+nativeCases+",\"native_permutation_cases\":"+permutationCases+",\"checks\":"+checks+",\"maximum_absolute_difference\":"+maximum+"}");
    }
}
